"""Build a gamma line table from a Geant4 ion-mode run, for use with /generator/spectrumFile.

Run the simulation once with ``/generator/mode ion`` (Bi214 or Tl208 at rest on the skin). Every gamma that
Geant4's own radioactive-decay data emits is recorded in the LXeGammas tree; this script merges them into
lines and writes a table that ``/generator/mode lines`` reads::

    # E_MeV   intensity   sampling_weight
    0.60931   45.49       45.49

``intensity`` is gammas per 100 decays (the generator only uses ratios). ``sampling_weight`` controls how
often the line is drawn; the generator reweights each event by intensity / sampling, so a boosted line is
still counted with its physical weight. Without ``--boost-*`` the sampling weight equals the intensity and
every event weight is 1.

Usage::

    python make_line_table.py runtime/LXe_output.root -o Bi214_lines.txt
    python make_line_table.py runtime/LXe_output.root -o Bi214_boosted.txt --boost-above 2.0 --boost-factor 20

Lines drawn from the table are single gammas. Cascade summing (e.g. 609 + 1764 keV from one decay) is not
produced by lines mode; use ion mode as the reference for that.
"""
import argparse
from pathlib import Path

import numpy as np
import uproot


def read_gammas(path):
    """Return (gamma energies in MeV, number of decays simulated)."""
    with uproot.open(path) as root:
        if "LXeGammas" not in root or "LXeEvents" not in root:
            raise SystemExit(f"{path} has no LXeGammas/LXeEvents tree: was it produced with '/generator/mode ion'?")
        energies = root["LXeGammas"]["E"].array(library="np")
        n_decays = root["LXeEvents"].num_entries
    return np.asarray(energies, dtype=float), int(n_decays)


def merge_lines(energies, merge_mev):
    """Group sorted energies into lines. Returns (line energies, counts)."""
    energies = np.sort(energies)
    if energies.size == 0:
        return np.array([]), np.array([], dtype=int)
    breaks = np.flatnonzero(np.diff(energies) > merge_mev) + 1
    groups = np.split(energies, breaks)
    return np.array([g.mean() for g in groups]), np.array([g.size for g in groups])


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("root_file", help="LXe_output.root from a '/generator/mode ion' run")
    parser.add_argument("-o", "--output", required=True, help="line table to write")
    parser.add_argument("--decays", type=int, default=None,
                        help="number of decays simulated (default: rows of the LXeEvents tree)")
    parser.add_argument("--merge-kev", type=float, default=0.2, help="lines closer than this are merged (default 0.2)")
    parser.add_argument("--min-intensity", type=float, default=0.01,
                        help="drop lines below this many gammas per 100 decays (default 0.01)")
    parser.add_argument("--min-energy", type=float, default=0.0, help="drop lines below this energy in MeV (default 0)")
    parser.add_argument("--boost-above", type=float, default=None,
                        help="oversample lines at or above this energy in MeV (needs --boost-factor)")
    parser.add_argument("--boost-factor", type=float, default=None,
                        help="sampling weight = intensity x this factor for the boosted lines")
    args = parser.parse_args()

    if (args.boost_above is None) != (args.boost_factor is None):
        parser.error("--boost-above and --boost-factor go together")
    if args.boost_factor is not None and args.boost_factor <= 0:
        parser.error("--boost-factor must be positive")

    energies, n_decays = read_gammas(args.root_file)
    if args.decays is not None:
        n_decays = args.decays
    if n_decays <= 0:
        raise SystemExit("no decays in the file")
    if energies.size == 0:
        raise SystemExit("the LXeGammas tree is empty: no decay gammas were recorded (is the RadioactiveDecay physics on?)")

    line_e, counts = merge_lines(energies, args.merge_kev/1000.)
    intensity = 100.*counts/n_decays                  # gammas per 100 decays
    error = 100.*np.sqrt(counts)/n_decays

    keep = (intensity >= args.min_intensity) & (line_e >= args.min_energy)
    dropped = (~keep).sum()
    line_e, counts, intensity, error = line_e[keep], counts[keep], intensity[keep], error[keep]
    if line_e.size == 0:
        raise SystemExit("no line survives the cuts")

    sampling = intensity.copy()
    if args.boost_above is not None:
        sampling[line_e >= args.boost_above] *= args.boost_factor

    out = Path(args.output)
    out.parent.mkdir(parents=True, exist_ok=True)
    with out.open("w") as f:
        f.write(f"# generated by make_line_table.py from {Path(args.root_file).name}\n")
        f.write(f"# decays simulated: {n_decays}, gammas recorded: {energies.size}, lines written: {line_e.size}"
                f" (dropped {dropped})\n")
        f.write(f"# merge window {args.merge_kev} keV, min intensity {args.min_intensity}, min energy {args.min_energy} MeV\n")
        if args.boost_above is not None:
            f.write(f"# lines >= {args.boost_above} MeV oversampled x{args.boost_factor}; the generator weights events by intensity/sampling\n")
        f.write("# E_MeV    intensity_per_100_decays   sampling_weight   # counts\n")
        for e, i, s, c in zip(line_e, intensity, sampling, counts):
            f.write(f"{e:.5f}   {i:.5g}   {s:.5g}   # {c}\n")

    print(f"{n_decays} decays, {energies.size} gammas -> {line_e.size} lines written to {out} (dropped {dropped})")
    top = np.argsort(intensity)[::-1][:8]
    for k in top:
        print(f"  {line_e[k]:.5f} MeV   {intensity[k]:8.3f} +- {error[k]:.3f} per 100 decays")


if __name__ == "__main__":
    main()
